const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const vendored_dep = b.dependency("jsbsim", .{});

    const lib = b.addLibrary(.{
        .name = "jsbsim",
        .root_module = b.createModule(.{
            .target = target,
            .optimize = optimize,
            .link_libc = true,
            .link_libcpp = true,
        }),
        .linkage = .static,
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources,
        .root = vendored_dep.path("src"),
    });
    lib.root_module.addCSourceFile(.{
        .file = b.path("src/wrapper.cpp"),
    });
    lib.root_module.addIncludePath(vendored_dep.path("src"));
    lib.root_module.addCMacro("JSBSIM_VERSION", "\"jsbsim.toto-flight\"");
    b.installArtifact(lib);

    const bindings_c = b.addTranslateC(.{
        .root_source_file = b.path("src/wrapper.h"),
        .link_libc = true,
        .optimize = optimize,
        .target = target,
    });
    bindings_c.addIncludePath(vendored_dep.path("src"));
    const bindings_mod = bindings_c.addModule("bindings");
    bindings_mod.linkLibrary(lib);
}

